def solve_tiling(I):
    R,C=len(I),len(I[0])
    cells=[(i,j) for i in range(R) for j in range(C) if I[i][j]==8]
    cs=set(cells)
    tiles=[]
    for i in range(R-1):
        for j in range(C-1):
            blk=[(i+di,j+dj) for di in (0,1) for dj in (0,1)]
            n=sum(1 for c in blk if c in cs)
            if n==4: tiles.append(('full',frozenset(blk),blk))
            elif n==3:
                miss=[c for c in blk if c not in cs][0]
                tiles.append((miss,frozenset(blk),blk))
    res=[]
    def bt(rem,acc):
        if not rem: res.append(list(acc)); return
        c=min(rem)
        for name,s,blk in tiles:
            if c in s and s<=rem:
                acc.append((name,s)); bt(rem-s,acc); acc.pop()
    bt(cs,[])
    return res
