import json
def transform(I):
    R,C=len(I),len(I[0])
    cs=frozenset((i,j) for i in range(R) for j in range(C) if I[i][j]==8)
    tiles=[]
    pos={(0,0):'TL',(0,1):'TR',(1,0):'BL',(1,1):'BR'}
    for i in range(R-1):
        for j in range(C-1):
            blk=[(i+di,j+dj) for di in (0,1) for dj in (0,1)]
            inc=frozenset(c for c in blk if c in cs)
            if len(inc)==4:
                tiles.append(('sq',inc))
                for m in blk: tiles.append((pos[(m[0]-i,m[1]-j)],inc-{m}))
            elif len(inc)==3:
                m=[c for c in blk if c not in inc][0]
                tiles.append((pos[(m[0]-i,m[1]-j)],inc))
    res=[]
    def bt(rem,acc):
        if not rem: res.append(list(acc)); return
        if len(res)>10: return
        c=min(rem)
        for name,s in tiles:
            if c in s and s<=rem: bt(rem-s,acc+[(name,s)])
    bt(cs,[])
    uniq={tuple(sorted((n,tuple(sorted(s))) for n,s in t)) for t in res}
    assert len(uniq)==1, len(uniq)
    cmap={'sq':1,'TL':2,'BL':3,'TR':4,'BR':5}
    out=[[0]*C for _ in range(R)]
    for n,s in uniq.pop():
        for c in s: out[c[0]][c[1]]=cmap[n]
    return out
